int spiral_order(int matrix[][8],int rows,int columns,int result[]){int top;int bottom;int left;int right;int i;int count;top=0;bottom=rows-1;left=0;right=columns-1;count=0;while(top<=bottom&&left<=right){for(i=left;i<=right;i=i+1)result[count++]=matrix[top][i];top=top+1;for(i=top;i<=bottom;i=i+1)result[count++]=matrix[i][right];right=right-1;if(top<=bottom){for(i=right;i>=left;i=i-1)result[count++]=matrix[bottom][i];bottom=bottom-1;}if(left<=right){for(i=bottom;i>=top;i=i-1)result[count++]=matrix[i][left];left=left+1;}}return count;}
int main(void){int m[8][8];int r[64];int e[9]={1,2,3,6,9,8,7,4,5};int i;int j;int v;v=1;for(i=0;i<3;i=i+1)for(j=0;j<3;j=j+1)m[i][j]=v++;if(spiral_order(m,3,3,r)!=9)return 1;for(i=0;i<9;i=i+1)if(r[i]!=e[i])return 2;return 42;}
